from pathlib import Path
import json
base=Path(__file__).resolve().parents[1]
data=json.loads((base/'evidence.json').read_text())
template="import { Stack, Row, Grid, H1, H2, Text, Table, Button, Link, useState, useHostTheme } from \"cursor/canvas\";\nconst evidence = __DATA__;\nexport default function LatestResults() {\n const theme = useHostTheme();\n const [filter,setFilter] = useState(\"All\");\n const [selected,setSelected] = useState(\"Sybil scaling\");\n const rows = evidence.studies.filter(s=>filter===\"All\"||s.group===filter);\n const active = rows.find(s=>s.name===selected)||rows[0];\n return <Stack gap={18} style={{padding:28,maxWidth:1180,margin:\"0 auto\",color:theme.text.primary}}>\n  <Text style={{color:theme.text.secondary}}>SWARM LAB · RESULTS REVIEW · {evidence.cutoff}</Text>\n  <H1>Trustworthy evidence is the recurring bottleneck</H1>\n  <Text>Sybil checking and market splitting provide the clearest bounded findings. New Opus configurations recover two baselines. Several other studies expose weak evidence acquisition, correlated reports or unnecessary action, without demonstrating a benefit from additional agents.</Text>\n  <Grid columns=\"repeat(auto-fit,minmax(240px,1fr))\" gap={24}>\n   <Stack gap={6}><H2>Strongest completed</H2><Text>Sybil checking: +52.8 points on the paired scaling contrast. Market splitting: 6/6 firm-regulated versus 0/6 owner-regulated markets.</Text></Stack>\n   <Stack gap={6}><H2>Important change</H2><Text>Discussion clean gate: 12/12. Compositional Q0: 24/24 safe. Earlier failures remain historical; broader intervention effects remain untested.</Text></Stack>\n   <Stack gap={6}><H2>Claims to resist</H2><Text>More checks always help; more agents add value; done means qualified; thousands of calls mean thousands of independent samples.</Text></Stack>\n  </Grid>\n  <H2>Evidence and disposition</H2>\n  <Text style={{color:theme.text.secondary}}>Select a study for its result, actual sample unit, limitations and next scientific decision. Source reports cover work through 4 October 2026; all values are observed study summaries, not forecasts.</Text>\n  <Row gap={8} wrap>{[\"All\",\"Completed findings\",\"Qualification / diagnostics\",\"Still running\"].map(f=><Button key={f} variant={filter===f?\"primary\":\"secondary\"} onClick={()=>{setFilter(f);setSelected(evidence.studies.find(s=>f===\"All\"||s.group===f)!.name);}}>{f}</Button>)}</Row>\n  <Table headers={[\"Study · select for details\",\"Evidence type\",\"Assessment\"]} rows={rows.map(s=>[<Button key={s.name} variant={active.name===s.name?\"primary\":\"ghost\"} onClick={()=>setSelected(s.name)}>{s.name}</Button>,s.group,s.verdict])}/>\n  <Stack gap={12} style={{padding:20,background:theme.fill.quaternary,borderTop:`1px solid ${theme.stroke.primary}`}}>\n   <H2>{active.name}</H2>\n   <Text weight=\"semibold\">{active.result}</Text>\n   <Text><strong>Sample:</strong> {active.sample}</Text>\n   <Text><strong>Assessment:</strong> {active.reading}</Text>\n   <Text><strong>Limits:</strong> {active.limit}</Text>\n   <Text><strong>Next:</strong> {active.next}</Text>\n   <Row gap={14} wrap>{active.sources.map((s,i)=><Link key={s.url} href={s.url}>Source {i+1}: {s.path.split(\"/\").slice(-2).join(\"/\")}</Link>)}</Row>\n  </Stack>\n  <H2>What I would prioritize</H2>\n  <Text><strong>1.</strong> Finish the admitted comparisons before interpreting partial cells. Keep qualification and scientific outcomes separate.</Text>\n  <Text><strong>2.</strong> In the Sybil family, manipulate truth scarcity and admission at equal cost. Another large model-only replication is less informative than testing the information bottleneck directly.</Text>\n  <Text><strong>3.</strong> Require each extra agent or protocol step to beat the simpler baseline. Healing ties Jev alone; Theseus needs a compute-matched comparison; exact deduplication is the essential Quorum baseline.</Text>\n  <Text><strong>4.</strong> Repair Capture-memory MP3's retry accounting, round caption and impossible hub fraction before combining models into a headline.</Text>\n  <H2>Review scope</H2>\n  <Text>{evidence.scope}</Text>\n  <Text>Selected arithmetic checked: all 36 Market episode rows and 6/6 versus 0/6 versus 0/6 evasion counts; all 120 Sybil budget cells and seven joint-target crossings; the 24 paired scaling differences; saved Qwen purge endpoints. Model configurations, task roots and redesigned cohorts remain separate. Most results depend on small numbers of synthetic task/world clusters and same-owner audits.</Text>\n  <Link href=\"https://swarm-live.pages.dev/\">Open the live dashboard</Link>\n </Stack>;\n}\n"
output=Path('/Users/halcyon/.cursor/projects/Users-halcyon-swarm-labs-agentops/canvases/latest-experiment-results.canvas.tsx')
output.write_text(template.replace('__DATA__',json.dumps(data,separators=(',',':'),ensure_ascii=False)))
print(output)

